INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 18, 'theory', 'Quiz: transactions and isolation');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 18, 0, 'Two transactions read a balance of 100 and each wrote 110 (+10 in the application). What is this anomaly called and how is it cured?', '["Dirty read — by raising the level to READ UNCOMMITTED", "Phantom — by adding an index", "Deadlock — by reducing the timeout", "Lost update — by an atomic UPDATE bal = bal + 10 or by locking the row"]', 3, 'The pattern "read, change in the application, write" loses one of the changes. Do the arithmetic in the database in one query, or lock the row (FOR UPDATE), or check a version.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 18, 1, 'What does the REPEATABLE READ isolation level mean?', '["Each query sees the freshest committed data", "The data snapshot is fixed for the whole transaction: rereading a row gives the same value", "Transactions run strictly one after another", "Reading other transactions'' uncommitted changes is allowed"]', 1, 'READ COMMITTED takes a new snapshot for every query, REPEATABLE READ one per transaction, and SERIALIZABLE guarantees a result as with serial execution.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 18, 2, 'How does MVCC let readers not block writers?', '["Every change creates a new row version, and a reader sees the versions from its own snapshot", "The writer waits until the reader finishes", "Readers get a copy of the whole table", "Writers work only at night"]', 0, 'The old version stays as long as some snapshot needs it; versions nobody needs are later removed by background cleanup (vacuum in PostgreSQL).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 18, 3, 'Transaction T1 holds row A and waits for B, while T2 holds B and waits for A. What does the database do?', '["Waits forever", "Merges the transactions into one", "Finds the cycle in the wait graph and rolls back one of the transactions (deadlock)", "Ignores the locks"]', 2, 'The main way to avoid deadlocks is to take locks in one order and keep transactions short; the application retries the rolled-back transaction.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 18, 4, 'Why is COMMIT confirmed only after the fsync of the log (WAL)?', '["To speed up reads", "So that a confirmed transaction survives a power failure: after a crash the log is replayed", "To avoid using indexes", "It is a requirement of CHECK constraints"]', 1, 'Data pages may reach the disk later; the log is the source of truth for recovery. Turning fsync off speeds up the commit, but the risk of losing confirmed data returns.');
